import fs from 'fs';

function parseList(file) {
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  const entries = [];
  for (const line of lines) {
    const m = line.match(/^\s+(\S+\.(?:ts|html)):(\d+)\s/);
    if (m) entries.push({ file: m[1].split('\\').join('/'), lineNo: parseInt(m[2], 10) });
  }
  return entries;
}

const entries = [...parseList('/tmp/status.txt'), ...parseList('/tmp/fancy.txt')];
const byFile = new Map();
for (const e of entries) {
  if (!byFile.has(e.file)) byFile.set(e.file, new Set());
  byFile.get(e.file).add(e.lineNo);
}

let totalEdits = 0;
for (const [file, lineNos] of byFile) {
  const content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n');
  for (const lineNo of lineNos) {
    const idx = lineNo - 1;
    const before = lines[idx];
    const after = before.replace(/\bdisableTooltip\b/g, 'hideHint');
    if (after !== before) {
      lines[idx] = after;
      totalEdits++;
    } else {
      console.error('NO CHANGE at', file, lineNo, JSON.stringify(before));
    }
  }
  fs.writeFileSync(file, lines.join('\n'));
}
console.log('Files touched:', byFile.size, 'Edits:', totalEdits);

