import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { HintDirective } from "../../lib/hint.directive";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-58",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent, HintDirective ],
    template: `
        <app-card heading="Feature 58" disableTooltip>
            @for (item of items; track item.id) {
                <app-pill [label]="item.name" [variant]="item.variant" [hideHint]="item.hidden" />
            }
            <app-pill label="Plain" hideHint />
            <app-pill variant="success" label="Active" [hideHint]="!isActive" />
            <app-fancy-pill #fancyRef icon="bolt" label="Fancy" hideHint></app-fancy-pill>
            <small>Fancy hint: {{ fancyRef.hideHint() ? 'off' : 'on' }}</small>
            @if (disableTooltip) {
                <small>Hints are switched off on this screen</small>
            }
            <small appHint="More about feature 58" [hintDisabled]="!isActive">More</small>
        </app-card>
    `
})
export class Feature058Component {
    isActive = true;
    count = 2;
    title = "Title 58";
    statusVariant: PillVariant = "success";
    disableTooltip = false;
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: true } ];

    private readonly fancy = viewChild(FancyPillComponent);
    readonly allQuiet = computed(() => {
        if (!this.disableTooltip) return false;
        return this.fancy()?.disableTooltip() === true;
    });
}

import { ChangeDetectionStrategy, Component, viewChildren } from "@angular/core";
