    templateUrl: "./feature-69.component.html"
})
export class Feature069Component {
    isActive = false;
    count = 6;
    title = "Title 69";
    statusVariant: PillVariant = "success";

    private readonly pills = viewChildren(PillComponent);

    quietPills(): number {
        return this.pills().filter(pill => pill.disableTooltip()).length;
    }
}

import { ChangeDetectionStrategy, Component, viewChild } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillLegacyComponent } from "../../lib/pill-legacy.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-72",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent, PillLegacyComponent ],
    template: `
        <app-card heading="Feature 72" [disableTooltip]="true">
            <div class="row">
                <app-pill label="Info" variant="info" hideHint /><app-pill label="Active" variant="success" hideHint />
                <app-pill-legacy [label]="title" [variant]="statusVariant" [disableTooltip]="count > 3" />
            </div>
            <app-pill [label]="title" hideHint />
            <app-fancy-pill
                [icon]="count > 2 ? 'bolt' : 'star'"
                [hideHint]="count > 5"
                label="Fancy" />
        </app-card>
        <app-card heading="Summary" [disableTooltip]="!isActive" />
    `
})
export class Feature072Component {
    isActive = true;
    count = 2;
    title = "Title 72";
    statusVariant: PillVariant = "warning";

    private readonly fancy = viewChild.required(FancyPillComponent);
    private readonly firstPill = viewChild.required(PillComponent);

    hintCount(): number {
        const hidden = [ this.fancy().disableTooltip(), this.firstPill().disableTooltip() ];
        return hidden.filter(value => !value).length;
    }
}

